import Foundation
import XCTest
@testable import ColorComposerCore

/// Solver parity against the golden-vector corpus generated by the Elixir
/// service (viamin/color_matching#111).
///
/// The corpus lives at `Tests/Fixtures/parity/v1/corpus.json` — a verbatim
/// copy of `priv/parity/v1/corpus.json` from the `color_matching` repository.
/// Every scenario pins three layers of agreement with
/// `ColorMatching.WeightedSquaredError`:
///
/// 1. Per-candidate scores (including the `"excluded"` missing-measurement
///    outcome) match exactly.
/// 2. `CompositionSolver` selection (earliest-index-wins) reproduces the
///    expected `selected_index`, `error`, and selected hex color.
/// 3. Tie evidence (`tied_indices`, `tie_broke`) matches the corpus.
///
/// Expected values are exact dyadic rationals (weights like 1.5/0.25 against
/// channel deltas that are multiples of 1/16), so every arithmetic
/// intermediate is exactly representable in `Double` — the tests assert exact
/// equality, not approximate.
///
/// See `docs/solver-parity-corpus.md` for how to refresh the corpus.
final class SolverParityCorpusTests: XCTestCase {
    // MARK: - Corpus wire model

    private struct Corpus: Codable {
        let algorithmVersion: Int
        let lightSources: [String]
        let missingPolicy: String
        let scorer: String
        let selection: String
        let scenarios: [Scenario]
    }

    private struct Scenario: Codable {
        let id: String
        let description: String
        let palette: [Vector]
        let target: Vector
        let weights: [String: Double]
        let expected: Expected
    }

    private struct Vector: Codable {
        let index: Int?
        let hexColor: String
        let channels: [String: Double]
    }

    private struct Expected: Codable {
        let scores: [ScoreEntry]
        let selectedIndex: Int?
        let selectedHexColor: String?
        let error: Double?
        let tieBroke: Bool?
        let tiedIndices: [Int]
    }

    private struct ScoreEntry: Codable, Equatable {
        let index: Int
        let score: ParityScore
    }

    /// A score is either a finite number or the string `"excluded"`.
    private enum ParityScore: Equatable, Codable {
        case value(Double)
        case excluded

        enum DecodingError: Error { case unrecognized(String) }

        init(from decoder: Decoder) throws {
            let container = try decoder.singleValueContainer()
            if let value = try? container.decode(Double.self) {
                self = .value(value)
            } else if let raw = try? container.decode(String.self) {
                guard raw == "excluded" else { throw DecodingError.unrecognized(raw) }
                self = .excluded
            } else {
                throw DecodingError.unrecognized("expected a numeric score or \"excluded\"")
            }
        }

        func encode(to encoder: Encoder) throws {
            var container = encoder.singleValueContainer()
            switch self {
            case .value(let value): try container.encode(value)
            case .excluded: try container.encode("excluded")
            }
        }
    }

    // MARK: - Fixtures

    /// `Tests/Fixtures/parity/v1/corpus.json`, resolved relative to this file.
    private static var fixtureURL: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent() // ColorComposerCoreTests
            .deletingLastPathComponent() // Tests
            .appendingPathComponent("Fixtures/parity/v1/corpus.json")
    }

    private func loadCorpus() throws -> Corpus {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(Corpus.self, from: Data(contentsOf: Self.fixtureURL))
    }

    // MARK: - Corpus → domain mapping

    private func makeColor(_ vector: Vector) throws -> PaletteColor {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: value)
            }
        }
        let rgb = try XCTUnwrap(RGBColor(hex: vector.hexColor), "unparseable hex \(vector.hexColor)")
        return PaletteColor(id: vector.index ?? 0, hex: vector.hexColor, rgb: rgb, responses: responses)
    }

    private func makeTarget(_ vector: Vector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }

    /// Non-canonical weight keys (e.g. `ultraviolet`) are dropped, mirroring
    /// the server's handling of unknown light sources.
    private func makeWeights(_ raw: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: raw["white"] ?? 0,
            red: raw["red"] ?? 0,
            green: raw["green"] ?? 0,
            blue: raw["blue"] ?? 0,
            lps: raw["lps"] ?? 0
        )
    }

    /// Scorer output for every palette entry, in index order.
    private func actualScores(for scenario: Scenario) throws -> [ParityScore] {
        let scorer = WeightedSquaredErrorScorer()
        let target = makeTarget(scenario.target)
        let weights = makeWeights(scenario.weights)
        return try scenario.palette.map { vector in
            let color = try makeColor(vector)
            switch scorer.score(candidate: color, target: target, weights: weights) {
            case .score(let value): return .value(value)
            case .excluded: return .excluded
            }
        }
    }

    /// Scenarios whose target lacks a positively-weighted channel cannot be
    /// driven through `solve` (the app models that as a missing source image).
    private func isDrivable(_ scenario: Scenario) -> Bool {
        Set(makeWeights(scenario.weights).activeConditions.map(\.rawValue))
            .isSubset(of: scenario.target.channels.keys)
    }

    /// One 1×1 grid per active condition, filled with the target's values.
    private func grids(for scenario: Scenario) -> [LightingCondition: BrightnessGrid] {
        var grids: [LightingCondition: BrightnessGrid] = [:]
        for (condition, _) in makeWeights(scenario.weights).activeEntries {
            let value = scenario.target.channels[condition.rawValue] ?? 0
            grids[condition] = BrightnessGrid(width: 1, height: 1, values: [value])
        }
        return grids
    }

    private func scenario(_ id: String, in corpus: Corpus) throws -> Scenario {
        try XCTUnwrap(corpus.scenarios.first { $0.id == id }, "scenario \(id) missing from corpus")
    }

    // MARK: - Corpus integrity

    func testCorpusMetadataMatchesSupportedCorpusVersion() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, 1, "corpus algorithm_version changed — update this test deliberately")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, ["white", "red", "green", "blue", "lps"])
        XCTAssertEqual(corpus.scenarios.count, 12)
        let requiredScenarios: Set<String> = [
            "distinct-errors",
            "tie-symmetric-around-target",
            "tie-duplicate-vectors",
            "tie-three-way-on-lps",
            "missing-candidate-excluded",
            "missing-target-excluded",
            "zero-weight-channel-missing",
            "all-excluded",
            "single-channel-lps",
            "exact-match-zero-error",
            "unknown-weight-ignored",
            "mixed-large-palette",
        ]
        let ids = Set(corpus.scenarios.map(\.id))
        XCTAssertEqual(ids.count, corpus.scenarios.count, "duplicate scenario ids")
        XCTAssertTrue(requiredScenarios.isSubset(of: ids), "missing scenarios: \(requiredScenarios.subtracting(ids))")
    }

    func testCorpusPaletteIndicesMatchArrayPositions() throws {
        for scenario in try loadCorpus().scenarios {
            for (position, vector) in scenario.palette.enumerated() {
                XCTAssertEqual(vector.index, position, "scenario \(scenario.id)")
            }
        }
    }

    // MARK: - Parity

    func testScorerMatchesEveryExpectedScoreExactly() throws {
        for scenario in try loadCorpus().scenarios {
            let actual = try actualScores(for: scenario)
            XCTAssertEqual(actual, scenario.expected.scores.map(\.score), "scenario \(scenario.id)")
        }
    }

    func testSolverSelectionMatchesExpectedSelection() throws {
        for scenario in try loadCorpus().scenarios where isDrivable(scenario) {
            let palette = try scenario.palette.map(makeColor)
            let result = try CompositionSolver().solve(
                palette: palette,
                sourceGrids: grids(for: scenario),
                weights: makeWeights(scenario.weights)
            )
            XCTAssertEqual(result.colorIndices[0], scenario.expected.selectedIndex, "scenario \(scenario.id)")

            if let selected = scenario.expected.selectedIndex {
                let expectedError = try XCTUnwrap(scenario.expected.error, "scenario \(scenario.id)")
                let expectedHex = try XCTUnwrap(scenario.expected.selectedHexColor, "scenario \(scenario.id)")
                XCTAssertEqual(result.errors[0], expectedError, "scenario \(scenario.id)")
                XCTAssertEqual(result.palette[selected].hex, expectedHex, "scenario \(scenario.id)")
            } else {
                XCTAssertEqual(result.errors[0], Double.infinity, "scenario \(scenario.id)")
                XCTAssertEqual(result.unmatchedCellCount, 1, "scenario \(scenario.id)")
            }
            let excluded = scenario.expected.scores.filter { $0.score == .excluded }.count
            XCTAssertEqual(result.excludedCandidateCount, excluded, "scenario \(scenario.id)")
        }
    }

    func testTieMetadataMatchesEarliestIndexWinsSemantics() throws {
        for scenario in try loadCorpus().scenarios {
            let finite = try actualScores(for: scenario).enumerated().compactMap { offset, score -> (Int, Double)? in
                guard case .value(let value) = score else { return nil }
                return (offset, value)
            }
            guard let minimum = finite.map({ $0.1 }).min() else {
                XCTAssertTrue(scenario.expected.tiedIndices.isEmpty, "scenario \(scenario.id)")
                XCTAssertNil(scenario.expected.tieBroke, "scenario \(scenario.id)")
                continue
            }
            let tied = finite.filter { $0.1 == minimum }.map(\.0).sorted()
            XCTAssertEqual(tied, scenario.expected.tiedIndices, "scenario \(scenario.id)")
            XCTAssertEqual(tied.count > 1, scenario.expected.tieBroke == true, "scenario \(scenario.id)")
        }
    }

    /// A target missing a positively-weighted channel excludes every candidate
    /// at the scorer level; through the app's solver the same situation is the
    /// missing-source-image error for that channel.
    func testMissingTargetChannelExcludesEveryCandidateAndSolveThrows() throws {
        let corpus = try loadCorpus()
        let scenario = try scenario("missing-target-excluded", in: corpus)
        let palette = try scenario.palette.map(makeColor)
        let target = makeTarget(scenario.target)
        let weights = makeWeights(scenario.weights)
        let scorer = WeightedSquaredErrorScorer()

        for color in palette {
            XCTAssertEqual(scorer.score(candidate: color, target: target, weights: weights), .excluded)
        }

        // Grids only for the channels the target actually measured: white has
        // positive weight but no measurement, so the solver must refuse.
        var incompleteGrids: [LightingCondition: BrightnessGrid] = [:]
        for (key, value) in scenario.target.channels {
            if let condition = LightingCondition(rawValue: key) {
                incompleteGrids[condition] = BrightnessGrid(width: 1, height: 1, values: [value])
            }
        }

        XCTAssertThrowsError(
            try CompositionSolver().solve(palette: palette, sourceGrids: incompleteGrids, weights: weights)
        ) { error in
            XCTAssertEqual(error as? CompositionSolverError, .missingSourceGrid(.white))
        }
    }

    func testUnknownWeightKeysAreIgnored() throws {
        let corpus = try loadCorpus()
        let unknown = try scenario("unknown-weight-ignored", in: corpus)
        let distinct = try scenario("distinct-errors", in: corpus)

        XCTAssertEqual(unknown.weights["ultraviolet"], 3.0, "corpus no longer exercises an unknown weight key")
        XCTAssertEqual(makeWeights(unknown.weights), makeWeights(distinct.weights))
        XCTAssertEqual(unknown.expected.scores, distinct.expected.scores)
        XCTAssertEqual(try actualScores(for: unknown), try actualScores(for: distinct))
    }
}

